const jobs=$('Read Jobs — Follow-Up Queue').all().map(x=>x.json);
const contacts=$('Read Contacts — Follow-Up Queue').all().map(x=>x.json);
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const out=[];
for(const j of jobs){
 const email=String(j['Contact Email']||'').toLowerCase();
 const c=contacts.find(x=>String(x.Email||'').toLowerCase()===email);
 const optedOut=String(c?.['Opted Out']||'N').toUpperCase()==='Y' || String(c?.['Contact State']||'').toLowerCase()==='do not contact';
 if(optedOut) continue;
 const status=String(j.Status||'');
 if(status==='Approved - Deferred' && j.Draft && j['Approved At']) { out.push({json:{...j,kind:'deferredInitial'}}); continue; }
 if(status==='Follow-Up Approved - Deferred' && j['Follow-Up Draft'] && j['Follow-Up Approved At']) { out.push({json:{...j,kind:'deferredFollowup'}}); continue; }
 const due=String(j['Follow-Up Due Date']||'').slice(0,10);
 if(status==='Sent' && j.Replied!=='Y' && due && due<=today && !j['Follow-Up Sent Date']) out.push({json:{...j,kind:'newFollowup'}});
 if(j.Replied==='Y' && due && !j['Follow-Up Sent Date']) out.push({json:{...j,kind:'replySkip','Status':'Replied — No Follow-Up','Follow-Up Due Date':''}});
}
return out;

