const j=$json;
const site=(()=>{try{return $('Fetch Portfolio Profile').first().json||{}}catch(e){return {}}})();
const profileName=String($env.PROFILE_NAME||site.name||'').trim();
const profileBio=String($env.PROFILE_BIO||site.bio||'').trim();
if(!profileName||!profileBio) throw new Error('Profile fields missing; check the portfolio endpoint and PORTFOLIO_URL.');
const sys=`You write a polite 60-100 word follow-up reply in an existing email thread. Use only the supplied applicant profile, original sent email, and job-posting facts. No new claims. Ask one combined question with exactly one question mark that asks BOTH (a) whether the recruiter has had a chance to review and (b) what specific improvement to the applicant's resume or what project would make the applicant a stronger fit for this team. Do not follow up if the recipient replied or opted out. Return strict JSON only: {"body":"..."}. Avoid: I hope this email finds you well, game-changer, reach out, synergy, passionate. No placeholders.`;
const user=`PROFILE NAME: ${profileName}. PROFILE BIO: ${profileBio}. Job: ${j['Job Title']} at ${j.Company}. Recruiter: ${j['Contact Name']}. Original email: ${j.Draft}. Posting facts: ${j['Posting Text']}. Recipient: ${j['Contact Email']}.`;
return [{json:{...j,profileName,profileBio,openaiBody:{model:$env.OPENAI_MODEL||'gpt-4.1-mini',temperature:0.2,response_format:{type:'json_object'},messages:[{role:'system',content:sys},{role:'user',content:user}]}}}];

// Hard deterministic gate. Run once for each draft item.
const j = $json;
const body = String(j.body ?? j.draft ?? j.emailBody ?? '').trim();
const expected = String(j.expectedEmail ?? j.apolloEmail ?? j['Contact Email'] ?? '').trim().toLowerCase();
const recipient = String(j.recipientEmail ?? j.to ?? j['Contact Email'] ?? '').trim().toLowerCase();
const verified = j.emailVerified === true || j['Email Verification'] === 'valid';
const words = body.match(/\b[\p{L}\p{N}][\p{L}\p{N}'’-]*\b/gu) ?? [];
const banned = ['i hope this email finds you well','game-changer','reach out','synergy','passionate'];
const lower = body.toLowerCase();
const bannedHits = banned.filter(p => lower.includes(p));
const placeholders = /\[[^\]]+\]|\{\{[^}]+\}\}|\b(?:YOUR_NAME|YOUR_EMAIL|RESUME_URL|PORTFOLIO_URL|COMPANY_NAME|RECRUITER_NAME|REPLACE_WITH_[A-Z0-9_]+)\b/i.test(body);
const minWords = Number(j.minWords ?? 60);
const maxWords = Number(j.maxWords ?? 120);
const questionMarks = (body.match(/\?/g) ?? []).length;
const reasons = [];
if (!body) reasons.push('empty body');
if (words.length < minWords || words.length > maxWords) reasons.push(`word count ${words.length} outside ${minWords}-${maxWords}`);
if (questionMarks !== 1) reasons.push(`expected exactly one question mark; found ${questionMarks}`);
if (bannedHits.length) reasons.push(`banned phrase(s): ${bannedHits.join(', ')}`);
if (placeholders) reasons.push('leftover placeholder detected');
if (!expected || recipient !== expected) reasons.push('recipient does not match Apollo result');
if (!verified) reasons.push('email has not passed verification');
return [{json:{...j, body, wordCount:words.length, questionMarks, gatePassed:reasons.length===0, gateReasons:reasons}}];

